def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def canonical_hash(value):
    return hashlib.sha256(json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()).hexdigest()

def source(sid, title, authors, year, url, doi, pmid, kind, design, finding, locator, limitation, counter):
    return dict(source_id=sid, title=title, authors=authors, year=year, url=url, doi=doi,
                pmid=pmid, source_type=kind, access="FULL_TEXT", accessed_on=DATE,
                verified=True, prescriptive_support_eligible=True,
                population_design_dose=design, findings=finding, locator=locator,
                limitations=[limitation], counterevidence=[counter])

