def build():
    registry = json.loads(REG.read_text(encoding="utf-8-sig"))
    raw = sha(REG)
    records = []
    entries = []
    for policy in registry["policies"]:
        n = int(policy["policyId"].split("P")[-1])
        disposition, skeys, rationale, conditions = P[n]
        approved = disposition.startswith("APPROVE")
        sources = [S[k] for k in skeys]
        eligible_ids = [s["source_id"] for s in sources if s["prescriptive_support_eligible"]]
